/**
 * Per-environment values, served as /config.json next to the app and generated by the
 * serverless Terraform stack (so one build artifact works in dev and prd).
 */
export interface RuntimeConfig {
  env: string;
  /** API Gateway base URL, e.g. https://xxx.gateway.dev */
  apiBase: string;
  firebase: { apiKey: string; projectId: string; authDomain: string };
}

export function parseRuntimeConfig(raw: unknown): RuntimeConfig {
  const o = raw as Partial<RuntimeConfig> | null;
  const fb = o?.firebase;
  if (
    !o ||
    typeof o.env !== 'string' ||
    typeof o.apiBase !== 'string' ||
    !fb ||
    typeof fb.apiKey !== 'string' ||
    typeof fb.projectId !== 'string' ||
    typeof fb.authDomain !== 'string'
  ) {
    throw new Error('Invalid /config.json: expected { env, apiBase, firebase: { apiKey, projectId, authDomain } }');
  }
  return { env: o.env, apiBase: o.apiBase, firebase: fb };
}

export async function loadRuntimeConfig(url = '/config.json'): Promise<RuntimeConfig> {
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) throw new Error(`Cannot load ${url}: HTTP ${res.status}`);
  // A missing file is often answered with the SPA fallback page (HTML), not a 404.
  const body: unknown = await res.json().catch(() => {
    throw new Error(`Invalid ${url}: not JSON (is it deployed next to the app?)`);
  });
  return parseRuntimeConfig(body);
}
